function hexToRgb(hex:string) {
 const raw=hex.replace('#','');
 const value=raw.length===3?raw.split('').map(ch=>ch+ch).join(''):raw;
 const parsed=Number.parseInt(value,16);
 return {r:(parsed>>16)&255,g:(parsed>>8)&255,b:parsed&255};
}
function relativeLuminance(hex:string) {
 const rgb=hexToRgb(hex);
 const channel=(value:number)=>{const c=value/255;return c<=0.03928?c/12.92:Math.pow((c+0.055)/1.055,2.4)};
 return 0.2126*channel(rgb.r)+0.7152*channel(rgb.g)+0.0722*channel(rgb.b);
}
function contrastRatio(foreground:string,background:string) {
 const a=relativeLuminance(foreground),b=relativeLuminance(background);
 const light=Math.max(a,b),dark=Math.min(a,b);
 return (light+0.05)/(dark+0.05);
}
function hueFromWheel(event:MouseEvent<HTMLButtonElement>) {
 const rect=event.currentTarget.getBoundingClientRect();
 const x=event.clientX-rect.left-rect.width/2;
 const y=event.clientY-rect.top-rect.height/2;
 if(Math.hypot(x,y)<rect.width*.16) return null;
 return Math.round((Math.atan2(y,x)*180/Math.PI+90+360)%360);
}

export function ComponentActivity({lesson,onComplete,completed=false}:{lesson:Lesson;onComplete?:(reflection:string)=>void;completed?:boolean}) {
 const brief=componentExperiments[lesson.id];
 const correct=lesson.id.length%3;
 const [example,setExample]=useState(0),[reset,setReset]=useState(0),[visited,setVisited]=useState<number[]>(completed?[0,1]:[]),[feedback,setFeedback]=useState(''),[answer,setAnswer]=useState<number|null>(completed?correct:null),[saved,setSaved]=useState(completed);
 if(!brief) return <p>This component’s activity could not be loaded.</p>;
 const options=[`Use it for this job: ${lesson.summary}`,'Choose it only because it looks more modern.','Use it in every screen without considering the task.'];
 // Rotate the correct position so the reflection is not always a first-option exercise.
 const choices=[...options];[choices[0],choices[correct]]=[choices[correct],choices[0]];
 return <section className="activity-shell component-lesson" aria-label={`${lesson.name} activity`}>
  <div className="activity-title"><span className="eyebrow">COMPONENT LAB / {lesson.name}</span><button onClick={()=>{setReset(n=>n+1);setFeedback('Activity reset. Try the task again.');setVisited([]);setAnswer(null);setSaved(false)}}>Reset activity</button></div>
  <h2 className="activity-goal">{brief.task}</h2><p className="component-intro">{lesson.summary} Try both examples below; they demonstrate the same component in different tasks.</p>
  <div className="component-example-buttons" role="group" aria-label="Choose a practical example">{brief.contexts.map((context,i)=><button key={context} aria-pressed={example===i} className={example===i?'selected':''} onClick={()=>{setExample(i);setFeedback('');}}><span>EXAMPLE {i+1}{visited.includes(i)?' · tried':''}</span>{context}</button>)}</div>
  <div className="component-experiment"><div className="component-stage"><span className="eyebrow">LIVE VISUAL EXAMPLE · {brief.contexts[example]}</span><ComponentDemo key={`${lesson.id}-${example}-${reset}`} id={lesson.id} example={example} report={message=>{setFeedback(message);setVisited(v=>v.includes(example)?v:[...v,example]);}}/></div><aside className="component-coach"><span className="eyebrow">WHAT TO NOTICE</span><h3>What problem does it solve?</h3><p>{brief.lesson}</p><h3>Your experiment</h3><p role="status" className="component-observation">{feedback||'Use the example. Your action and its effect will be explained here.'}</p><p className="component-local-note">Learning simulation. Changes stay inside this example.</p></aside></div>
  <fieldset className="component-reflection"><legend>Check your understanding: when would you choose {lesson.name.toLowerCase()}?</legend>{choices.map((choice,i)=><label key={choice} className={answer===i?'selected':''}><input type="radio" name={`reflection-${lesson.id}`} checked={answer===i} onChange={()=>{setAnswer(i);setSaved(false)}}/>{choice}</label>)}</fieldset>
  {answer!==null&&<div className={`component-answer ${answer===correct?'answer-correct':''}`} role="status"><strong>{answer===correct?'That is the right connection.':'Consider the task first.'}</strong><p>{answer===correct?brief.lesson:`Appearance alone does not establish a useful fit. ${lesson.summary} Choose the answer that describes that job.`}</p></div>}
  <div className="component-completion"><button className={saved?'completed':'primary'} disabled={visited.length<2||answer!==correct||saved} onClick={()=>{onComplete?.(`${lesson.name}: ${brief.lesson}`);setSaved(true)}}>{saved?'✓ Lesson completed':'Complete lesson'}</button><p role="status">{saved?'Your reflection is saved in My Progress.':visited.length<2?`Try an interaction in ${visited.length===0?'both examples':'the other example'}, then answer the question.`:answer!==correct?'Choose the answer that matches the component’s job.':'Ready to save your learning.'}</p></div>
 </section>;
}

