  const palette=paletteOffsets.map((offset,i)=>`hsl(${(hue+offset)%360} ${Math.max(28,Math.min(96,saturation-(i===3?12:0)))}% ${Math.max(18,Math.min(86,lightness+(i-2)*9))}%)`);
